-- Catálogo confirmado de Contanos un poco más. Conserva opciones históricas.
begin;
-- Liberar posiciones sin eliminar IDs referenciados por respuestas anteriores.
update public.opciones_comerciales set posicion = posicion + (select coalesce(max(posicion),0) + 10 from public.opciones_comerciales) where pregunta_id in (select id from public.preguntas_comerciales where codigo in ('servicio','proyecto','etapa'));
update public.opciones_comerciales set habilitada = false where pregunta_id in (select id from public.preguntas_comerciales where codigo in ('servicio','proyecto','etapa'));
update public.preguntas_comerciales set enunciado = '¿Qué servicio te interesa?', posicion = 1, habilitada = true where codigo = 'servicio';
update public.preguntas_comerciales set enunciado = '¿Para qué tipo de proyecto?', posicion = 2, habilitada = true where codigo = 'proyecto';
update public.preguntas_comerciales set enunciado = '¿En qué etapa estás?', posicion = 3, habilitada = true where codigo = 'etapa';
commit;
